import{_ as t,c as n,o as e,ae as i}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"How to Install and Activate Ninja Tables Plugin","description":"How to Install and Activate Ninja Tables Plugin","frontmatter":{"title":"How to Install and Activate Ninja Tables Plugin","description":"How to Install and Activate Ninja Tables Plugin"},"headers":[],"relativePath":"guide/getting-started/how-to-install-and-activate-ninja-tables-plugin.md","filePath":"guide/getting-started/how-to-install-and-activate-ninja-tables-plugin.md"}'),l={name:"guide/getting-started/how-to-install-and-activate-ninja-tables-plugin.md"};function o(s,a,r,d,c,h){return e(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="how-to-install-and-activate-ninja-tables-plugin" tabindex="-1">How to Install and Activate Ninja Tables Plugin <a class="header-anchor" href="#how-to-install-and-activate-ninja-tables-plugin" aria-label="Permalink to &quot;How to Install and Activate Ninja Tables Plugin&quot;">​</a></h1><p>Ninja Tables is well known because of its ease of use and simple configuration. Installing and activating this plugin is as easy as pie. So when you are all set to <a href="https://ninjatables.com/docs/ninja-tables-introduction/" target="_blank" rel="noreferrer">get started with Ninja tables</a>, let’s see how to install and activate it.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>To use Ninja Tables, you’ll need the following:</p><ul><li>WordPress version 5.6 or higher</li><li>PHP version 7.1 or higher</li></ul><h2 id="install-and-activate-ninja-tables" tabindex="-1">Install and Activate Ninja Tables <a class="header-anchor" href="#install-and-activate-ninja-tables" aria-label="Permalink to &quot;Install and Activate Ninja Tables&quot;">​</a></h2><p>Installing Ninja Tables is similar to any other WordPress plugin.</p><ul><li>Go to the WordPress Admin <strong>Dashboard</strong> → <strong>Plugins</strong> → <strong>Add New</strong>.</li><li>Search for <strong>Ninja Tables</strong>, click on the <strong>Install Now</strong> button, and then <strong>Activate</strong> it. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Install-and-activate-Ninja-Tables-1-1024x374.png" alt="Install and activate Ninja Tables"></li></ul><h2 id="alternative-method" tabindex="-1">Alternative Method <a class="header-anchor" href="#alternative-method" aria-label="Permalink to &quot;Alternative Method&quot;">​</a></h2><ul><li>Another way is to download the .<strong>zip</strong> file by clicking on the Download button.</li><li>Navigate to your WordPress Admin Panel → <strong>Plugins</strong> → <strong>Add New</strong> → <strong>Upload Plugin</strong>.</li><li>Click on Choose File, upload the .zip file, and click on <strong>Install Now</strong>. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Install-and-activate-Ninja-Tables-by-uploading-.zip.png" alt="Install and activate Ninja Tables by uploading .zip"></li></ul><h2 id="install-and-activate-pro-tutorial-video" tabindex="-1">Install and activate pro tutorial [Video] <a class="header-anchor" href="#install-and-activate-pro-tutorial-video" aria-label="Permalink to &quot;Install and activate pro tutorial [Video]&quot;">​</a></h2><p>The section is for those who are more comfortable with video rather than text tutorials. Below is an in-depth video tutorial on how you can install and activate Ninja Tables. <a href="https://youtu.be/VTOq48oO4cY?si=t5rGVXca-11Yp7WL" target="_blank" rel="noreferrer">https://youtu.be/VTOq48oO4cY?si=t5rGVXca-11Yp7WL</a></p>',12)])])}const p=t(l,[["render",o]]);export{g as __pageData,p as default};
